sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {
	//var url = gs.getProperty("glide.servlet.uri") + "services?id=hoc_hrm_todos_page&amp;table=sn_hr_core_task&amp;sys_id=" + current.sys_id;
	var url = gs.getProperty('glide.servlet.uri') + '/now/hr/agent/record/'+ current.getTableName() + '/' + current.sys_id;
	//url = url + "&amp;lang=en";
	var label = "Ouvrir l'enregistrement";

	template.print("<a href=" + url + "><button>" + label + "</button></a>" );

})(current, template, email, email_action, event);
